mapper.select:
/* 검진기록 목록 조회(병원 일정 연결분, 연결 일정이 삭제됐어도 포함) */ SELECT C.CKUP_RCD_SN , C.SCHDL_SN , DATE(S.SCHDL_DT) AS CKUP_YMD , C.HSPTL_NM , C.CKUP_TYPE_CD , T.COM_CD_NM AS CKUP_TYPE_CD_NM , CASE WHEN S.DEL_YN = 'Y' THEN TRUE ELSE FALSE END AS SCHDL_DEL_YN FROM CKUP_RCD C JOIN SCHDL S ON S.SCHDL_SN = C.SCHDL_SN LEFT JOIN COM_CD T ON T.COM_CD = C.CKUP_TYPE_CD AND T.COM_CD_PRNT_SN IS NOT NULL WHERE S.PET_SN = #{petSn} AND S.SCHDL_KND_CD = #{hospitalCd} AND C.CKUP_RCD_STTS_CD = #{completedCd} AND C.DEL_YN = 'N'
AND S.SCHDL_DT >= MAKEDATE(#{cond.year}, 1) AND S.SCHDL_DT < DATE_ADD(MAKEDATE(#{cond.year}, 1), INTERVAL 1 YEAR)
AND C.CKUP_TYPE_CD = #{cond.ckupTypeCd}
ORDER BY S.SCHDL_DT DESC , C.CKUP_RCD_SN DESC

/* 같은 날짜 병원 일정 중 가장 먼저 등록된 일정 */
SELECT SCHDL_SN
  FROM SCHDL
 WHERE PET_SN = #{petSn}
   AND SCHDL_KND_CD = #{hospitalCd}
   AND DEL_YN = 'N'
   AND SCHDL_DT >= #{ymd}
   AND SCHDL_DT < DATE_ADD(#{ymd}, INTERVAL 1 DAY)
 ORDER BY SCHDL_SN
 LIMIT 1

/* 일정에 연결된 완료 상태 검진기록 존재 여부 */
SELECT EXISTS (
       SELECT 1
         FROM CKUP_RCD
        WHERE SCHDL_SN = #{schdlSn}
          AND CKUP_RCD_STTS_CD = #{completedCd}
          AND DEL_YN = 'N'
       )

mapper.insert:
/* 검진기록 등록 */
INSERT INTO CKUP_RCD
     ( RECPT_SN
     , SCHDL_SN
     , CKUP_TYPE_CD
     , CKUP_RCD_STTS_CD
     , RCD_SRC_CD
     , HSPTL_NM
     , CKUP_CN
     , CKUP_MEMO_CN
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID )
VALUES
     ( #{recptSn}
     , #{schdlSn}
     , #{ckupTypeCd}
     , #{ckupRcdSttsCd}
     , #{rcdSrcCd}
     , #{hsptlNm}
     , #{ckupCn}
     , #{ckupMemoCn}
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId} )

mapper.update:
/* 검진기록 수정 */
UPDATE CKUP_RCD
   SET SCHDL_SN     = #{record.schdlSn}
     , CKUP_TYPE_CD = #{record.ckupTypeCd}
     , HSPTL_NM     = #{record.hsptlNm}
     , CKUP_CN      = #{record.ckupCn}
     , CKUP_MEMO_CN = #{record.ckupMemoCn}
     , MDFR_ID      = #{actorId}
     , MDFCN_DT     = NOW()
 WHERE CKUP_RCD_SN = #{record.ckupRcdSn}

/* 검진기록 상태 변경 */
UPDATE CKUP_RCD
   SET CKUP_RCD_STTS_CD = #{sttsCd}
     , MDFR_ID          = #{actorId}
     , MDFCN_DT         = NOW()
 WHERE CKUP_RCD_SN = #{ckupRcdSn}

mapper.insert:
/* 검진기록 상태 이력 등록 */
INSERT INTO CKUP_RCD_STTS_HSTRY
     ( CKUP_RCD_SN
     , MBR_SN
     , BFR_STTS_CD
     , AFTR_STTS_CD
     , REG_DT )
VALUES
     ( #{ckupRcdSn}
     , #{mbrSn}
     , #{bfrSttsCd}
     , #{aftrSttsCd}
     , NOW() )

mapper.update:
/* 검진기록의 반복 예방 관리 삭제 처리 */
UPDATE REPT_PRVNT_MNG
   SET DEL_YN   = 'Y'
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE CKUP_RCD_SN = #{ckupRcdSn}
   AND DEL_YN = 'N'

/* 검진기록의 반복 예방 관리 반려동물 변경 */
UPDATE REPT_PRVNT_MNG
   SET PET_SN   = #{petSn}
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE CKUP_RCD_SN = #{ckupRcdSn}

/* 반려동물의 검진기록 전체 삭제 (반려동물 삭제, 연결 일정 삭제 여부와 무관) */
UPDATE CKUP_RCD C
  JOIN SCHDL S
    ON S.SCHDL_SN = C.SCHDL_SN
   SET C.DEL_YN   = 'Y'
     , C.MDFR_ID  = #{actorId}
     , C.MDFCN_DT = NOW()
 WHERE S.PET_SN = #{petSn}
   AND C.DEL_YN = 'N'
